function PVPArenaFormationInfoNode:Awake()
    ---@type UnityEngine.RectTransform
    self.transform = self.controller.transform
    self.parent = self.transform.parent
    self.uiCamera = UIModule.RootCanvas.defaultCamera

    local proxy = UIDragProxy.Create(self.controller.gameObject)
    proxy.onPointerBeginDrag = Bind(self, self.OnPointerBeginDrag)
    proxy.onPointerDrag = Bind(self, self.OnPointerDrag)
    proxy.onPointerEndDrag = Bind(self, self.OnPointerEndDrag)

    ---@type UITeamInfoNode
    self.teamInfoEnv = CfUtils.GetLuaScr(self.UITeamInfoNode.gameObject, UITeamInfoNode)
    if not isNull(self.teamInfoEnv) then
        self.teamInfoEnv:SetExcludeDialogs({
            {id = Constants.UITypeIds.PVPArenaFormationDialog}
        })
    end

    self.__EventRefreshTeamMember   = Events.AddListener(Constants.EventNames.RefeshTeamMember, Bind(self, self.OnEventRefreshTeamMember))
    self.__EventSkillCompoundChange = Events.AddListener(Constants.EventNames.SkillCompoundChange, Bind(self, self.OnEventSkillCompoundChange))

    local gameObject = self.controller.gameObject
    ---@type UnityEngine.Canvas
    KTool.GetOrAddComponent(gameObject, CanvasType)
    KTool.GetOrAddComponent(gameObject, GraphicRaycaster)
    ---@type Engine.UI.OrderTracker
    self.orderTracker = KTool.GetOrAddComponent(gameObject, OrderTrackerType)
end

function PVPArenaFormationInfoNode:OnDestroy()
    if self.__EventRefreshTeamMember then
        Events.RemoveListener(Constants.EventNames.RefeshTeamMember, self.__EventRefreshTeamMember)
        self.__EventRefreshTeamMember = nil
    end
    if self.__EventSkillCompoundChange then
        Events.RemoveListener(Constants.EventNames.SkillCompoundChange, self.__EventSkillCompoundChange)
        self.__EventSkillCompoundChange = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end


