---RefreshText
---刷新先后手文本
function PVPArenaFormationInfoNode:RefreshText(actionOrder)
    local index = self.index
    local text
    if index > 2 then
        text = TextConfig[index]
    else
        ---[第一场顺序，第二场顺序]，0后1先
        local order = checkNumber(actionOrder[index])
         text = TextConfig[order + 1]
    end
    self.Text.text = text

end

function PVPArenaFormationInfoNode:RefreshTeam()
    if isNull(self.teamInfoEnv) then return end
    local index = self.index
    local PVPArenaId = Constants.SpecialQuestId.PVPArenaId
    local data = teamComponent:GetTeamInfoByQuestId(PVPArenaId, index)
    self.teamInfoEnv:Refresh(data, PVPArenaId, index)
end

function PVPArenaFormationInfoNode:OnEventRefreshTeamMember()
    self:RefreshTeam()
    Events.Broadcast(Constants.EventNames.PVPArenaRefreshTeamMember, self.index)
end

function PVPArenaFormationInfoNode:OnEventSkillCompoundChange()
    self:RefreshTeam()
    Events.Broadcast(Constants.EventNames.PVPArenaRefreshTeamMember, self.index)
end

