function PVPArenaFormationInfoNode:OnPointerBeginDrag(eventData)
    if isNull(eventData) then return end
    if self.isDragging then
        return
    end
    self.isDragging = true
    self.orderTracker.addSortingOrder = 10
end

---@param eventData UnityEngine.EventSystems.PointerEventData
function PVPArenaFormationInfoNode:OnPointerDrag(eventData)
    if isNull(eventData) then return end

    local vec2
    local bool, vecNow = ScreenPointToLocalPointInRectangle(self.parent, eventData.position, self.uiCamera, vec2)
    self.transform.anchoredPosition = Vector3.New(vecNow.x, vecNow.y, 0)
end

function PVPArenaFormationInfoNode:OnPointerEndDrag(eventData)
    if isNull(eventData) then return end
    Events.Broadcast(Constants.EventNames.PVPArenaFormationInfoNodeEndDrag, self.index)
    self.orderTracker.addSortingOrder = 0
    self.isDragging = false
end

